## 三、底层细节：串口通信的完整解析实现

### 3.1 Go 语言串口初始化与轮询调度

```go
package serial

import (
	"fmt"
	"log"
	"strings"
	"time"

	"github.com/tarm/golang-seriarport/v2"
)

// PortConfig 串口配置参数
type PortConfig struct {
	Name        string        // 设备路径如 /dev/ttyUSB0
	BaudRate    int           // 波特率：9600/19200/38400/57600/115200
	DataBits    int           // 数据位：7/8
	StopBits    int           // 停止位：1/2
	Parity      string        // 校验位：N/E/O
	ReadTimeout time.Duration // 读取超时
}

// SerialPort 封装串口操作
type SerialPort struct {
	port      *serialport.Port
	config    PortConfig
	isOpen    bool
	lastError error
}

// NewSerialPort 创建并打开串口
func NewSerialPort(cfg PortConfig) (*SerialPort, error) {
	// 串口参数标准化：确保偶校验或无校验
	cfg.Parity = normalizeParity(cfg.Parity)
	cfg.DataBits = ensureDataBits(cfg.DataBits, cfg.Parity)

	sp := &SerialPort{
		config: cfg,
	}

	// 打开串口
	rawPort, err := serialport.NewPort(&serialport.Config{
		Name:        cfg.Name,
		Baud:        cfg.BaudRate,
		ReadTimeout: cfg.ReadTimeout,
	}, serialport.WithDataBits(cfg.DataBits),
		serialport.WithStopBits(serialport.StopBits(cfg.StopBits)),
		serialport.WithParity(normalizeParityEnum(cfg.Parity)),
	)
	if err != nil {
		return nil, fmt.Errorf("串口 %s 打开失败: %w", cfg.Name, err)
	}

	// 关键：设置缓冲区大小，防止粘包
	if err = rawPort.SetBufferSize(4096); err != nil {
		log.Printf("[WARN] 设置缓冲区失败: %v，将使用默认值", err)
	}

	sp.port = rawPort
	sp.isOpen = true
	log.Printf("[INFO] 串口 %s 已打开 (baud=%d, data=%d, stop=%d, parity=%s)",
		cfg.Name, cfg.BaudRate, cfg.DataBits, cfg.StopBits, cfg.Parity)
	return sp, nil
}

// normalizeParityEnum 将字符串校验位转为枚举
func normalizeParityEnum(p string) serialport.Parity {
	switch strings.ToUpper(p) {
	case "E":
		return serialport.EvenParity
	case "O":
		return serialport.OddParity
	default:
		return serialport.NoParity
	}
}

// ReadFrame 读取完整Modbus RTU帧（处理粘包/分包）
func (sp *SerialPort) ReadFrame() ([]byte, error) {
	var buffer []byte
	frameStartTime := time.Now()
	maxFrameDuration := time.Duration(sp.config.BaudRate/1000*3.5) * time.Microsecond
	if maxFrameDuration < 3*time.Millisecond {
		maxFrameDuration = 3 * time.Millisecond // 最低3.5字符间隔
	}

	for {
		// 非阻塞读取，每次最多读256字节
		chunk := make([]byte, 256)
		n, err := sp.port.Read(chunk)
		if n > 0 {
			buffer = append(buffer, chunk[:n]...)
		}
		if err != nil {
			if err != serialport.ErrTimeout {
				sp.lastError = err
				return nil, err
			}
		}

		// 检查是否收到完整帧：至少6字节（地址+功能码+数据+CRC）
		if len(buffer) >= 6 {
			// 尝试按帧长度解析
			if frameLen := tryParseModbusFrameLength(buffer); frameLen > 0 && len(buffer) >= frameLen {
				frame := buffer[:frameLen]
				// 清空缓冲区剩余数据（处理分包后的尾部残留）
				buffer = buffer[frameLen:]
				return frame, nil
			}
		}

		// 超时判断：超过 3.5 字符时间无新数据 → 视为一帧结束
		if time.Since(frameStartTime) > maxFrameDuration && len(buffer) > 0 {
			// 如果已有数据且超时，返回当前缓冲区
			frame := buffer
			buffer = nil
			return frame, nil
		}

		// 防止无限等待，最大超时 2s
		if time.Since(frameStartTime) > 2*time.Second {
			if len(buffer) > 0 {
				frame := buffer
				buffer = nil
				return frame, nil
			}
			return nil, fmt.Errorf("串口 %s 读取超时", sp.config.Name)
		}

		time.Sleep(1 * time.Millisecond)
	}
}

// tryParseModbusFrameLength 尝试解析Modbus RTU帧长度
func tryParseModbusFrameLength(data []byte) int {
	if len(data) < 6 {
		return 0
	}

	// 功能码判断：根据MBAP头（Modbus TCP）或RTU格式判断
	funcCode := data[1]

	// 标准Modbus RTU：0x01-0x0F, 0x10-0x17, 0x2B, 0x02-0x0D
	// 异常响应：0x80-0xFF
	switch {
	case funcCode >= 0x01 && funcCode <= 0x0D:
		// 读类指令：固定6字节响应（无数据段）或更多
		switch funcCode {
		case 0x01, 0x02: // Coils, Discrete Inputs
			return 4 // 地址+功能码+字节计数+CRC(2) = 但实际含数据
		}
	case funcCode >= 0x80:
		return 5 // 异常响应：地址+功能码+异常码+CRC(2)
	}

	// 动态解析：根据功能码和从站地址推断
	// 简化策略：找到有效的CRC校验结束位置
	for i := 4; i < len(data); i++ {
		// 尝试校验从开头到 i+1 的帧
		if isValidModbusCRC(data[:i+1]) {
			return i + 1
		}
	}

	return 0
}

// SendCommand 发送Modbus RTU命令并等待响应
func (sp *SerialPort) SendCommand(addr, funcCode byte, startAddr, quantity uint16) ([]byte, error) {
	// 构建请求帧
	frame := buildModbusRTUFrame(addr, funcCode, startAddr, quantity)

	// 清空接收缓冲区，防止旧数据干扰
	sp.flushRxBuffer()

	// 发送
	if _, err := sp.port.Write(frame); err != nil {
		return nil, fmt.Errorf("发送命令失败: %w", err)
	}

	// 计算最小响应等待时间
	minWait := time.Duration(len(frame)*10/sp.config.BaudRate) * time.Millisecond
	time.Sleep(minWait)

	// 读取响应
	return sp.ReadFrame()
}

// flushRxBuffer 清空接收缓冲区
func (sp *SerialPort) flushRxBuffer() {
	if sp.port == nil {
		return
	}
	// 尝试读取并丢弃缓冲区残留数据
	buf := make([]byte, 512)
	for {
		n, err := sp.port.Read(buf)
		if n == 0 || err != nil {
			break
		}
	}
}

